"""Release metadata: reads the version from the companion's `__version__` and writes the two generated files that carry it.

    python tools\\release_meta.py [--project-url URL] [--check]

* companion/version_info.txt  the Windows version resource of DeskMediaCompanion.exe (read by companion/DeskMediaCompanion.spec)
* installer/version.iss       the Inno Setup include with the same version (read by installer/DeskMediaCompanion.iss)

Both are generated (git-ignored): `desk_media_companion/__init__.py` is the single place a version number is edited. Nothing machine-
or person-specific goes into them: the company name is the project's, the copyright line has no personal name, and the year comes
from the last commit (so the same commit always produces the same files).

The 4-part Windows version is major.minor.patch.0; a suffix after the third number ("0.2.0rc1") is dropped from it and kept in the
text version.
"""
from __future__ import annotations

import argparse
import os
import re
import subprocess
import sys

ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), ".."))
INIT = os.path.join(ROOT, "companion", "desk_media_companion", "__init__.py")
VERSION_INFO = os.path.join(ROOT, "companion", "version_info.txt")
VERSION_ISS = os.path.join(ROOT, "installer", "version.iss")

COMPANY = "DeskMedia Display project"
PRODUCT = "DeskMedia Display"
DESCRIPTION = "DeskMedia Companion"
INTERNAL_NAME = "DeskMediaCompanion"
ORIGINAL_FILENAME = "DeskMediaCompanion.exe"


def read_version(path: str = INIT) -> str:
    with open(path, encoding="utf-8") as f:
        m = re.search(r'^__version__\s*=\s*["\']([^"\']+)["\']', f.read(), re.MULTILINE)
    if not m:
        raise SystemExit(f"no __version__ in {path}")
    return m.group(1)


def version_tuple(version: str) -> tuple[int, int, int, int]:
    m = re.match(r"^(\d+)\.(\d+)\.(\d+)", version)
    if not m:
        raise SystemExit(f"version '{version}' must start with major.minor.patch")
    major, minor, patch = (int(g) for g in m.groups())
    for n in (major, minor, patch):
        if n > 65535:
            raise SystemExit("a version part is larger than 65535 (Windows limit)")
    return major, minor, patch, 0


def _git(*args: str) -> str:
    try:
        out = subprocess.run(["git", *args], cwd=ROOT, capture_output=True, text=True, timeout=20)
        return out.stdout.strip() if out.returncode == 0 else ""
    except (OSError, subprocess.SubprocessError):
        return ""


def commit_year() -> int:
    """Year of the last commit (deterministic per commit); the current year when there is no git."""
    year = _git("log", "-1", "--format=%cd", "--date=format:%Y")
    if year.isdigit():
        return int(year)
    import datetime
    return datetime.date.today().year


def default_project_url() -> str:
    """The https URL of the repository's `origin` remote (without credentials or .git), or '' when there is none."""
    url = _git("remote", "get-url", "origin")
    m = re.match(r"^(?:https://(?:[^@/]+@)?|git@|ssh://git@)(github\.com)[:/]([\w.-]+/[\w.-]+?)(?:\.git)?/?$", url)
    return f"https://{m.group(1)}/{m.group(2)}" if m else ""


def copyright_line(year: int) -> str:
    return f"Copyright (c) {year} {COMPANY}"


def version_info_text(version: str, year: int) -> str:
    v4 = version_tuple(version)
    dotted = ".".join(str(n) for n in v4)
    return f"""# UTF-8
# Generated by tools/release_meta.py from desk_media_companion.__version__ - do not edit.
VSVersionInfo(
  ffi=FixedFileInfo(
    filevers={v4},
    prodvers={v4},
    mask=0x3f,
    flags=0x0,
    OS=0x40004,
    fileType=0x1,
    subtype=0x0,
    date=(0, 0)
    ),
  kids=[
    StringFileInfo(
      [
      StringTable(
        u'040904B0',
        [StringStruct(u'CompanyName', u'{COMPANY}'),
        StringStruct(u'FileDescription', u'{DESCRIPTION}'),
        StringStruct(u'FileVersion', u'{dotted}'),
        StringStruct(u'InternalName', u'{INTERNAL_NAME}'),
        StringStruct(u'LegalCopyright', u'{copyright_line(year)}'),
        StringStruct(u'OriginalFilename', u'{ORIGINAL_FILENAME}'),
        StringStruct(u'ProductName', u'{PRODUCT}'),
        StringStruct(u'ProductVersion', u'{version}')])
      ]),
    VarFileInfo([VarStruct(u'Translation', [1033, 1200])])
  ]
)
"""


def version_iss_text(version: str, year: int, url: str) -> str:
    v4 = ".".join(str(n) for n in version_tuple(version))
    lines = [
        "; Generated by tools/release_meta.py from desk_media_companion.__version__ - do not edit, do not commit.",
        f'#define AppVersion "{version}"',
        f'#define AppVersionInfo "{v4}"',
        f'#define AppCopyright "{copyright_line(year)}"',
    ]
    if url:
        lines.append(f'#define AppURL "{url}"')
    return "\n".join(lines) + "\n"


def write(path: str, text: str) -> None:
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(text)


def generate(project_url: str = "") -> tuple[str, str]:
    """`project_url`: '' = none (the default: a repository URL carries its owner's account name, which is the project owner's call,
    not the build's), 'origin' = the https URL of the `origin` remote, anything else = that URL."""
    version = read_version()
    year = commit_year()
    url = default_project_url() if project_url == "origin" else project_url
    write(VERSION_INFO, version_info_text(version, year))
    os.makedirs(os.path.dirname(VERSION_ISS), exist_ok=True)
    write(VERSION_ISS, version_iss_text(version, year, url))
    return version, url


def main(argv: list[str] | None = None) -> int:
    ap = argparse.ArgumentParser(description=__doc__.split("\n")[0])
    ap.add_argument("--project-url", default="", help="home page shown in Programs and Features: a URL, 'origin' (the GitHub URL of the origin "
                                                       "remote) or '' (the default: none)")
    ap.add_argument("--print-version", action="store_true", help="only print the version")
    args = ap.parse_args(argv)
    if args.print_version:
        print(read_version())
        return 0
    version, url = generate(args.project_url)
    if args.project_url == "origin" and not url:
        print("note: the origin remote is not a GitHub https/ssh URL: no project URL")
    print(f"version {version} -> {os.path.relpath(VERSION_INFO, ROOT)}, {os.path.relpath(VERSION_ISS, ROOT)}" + (f" (url {url})" if url else " (no url)"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
